   169→// MerkleProof computes a proof from a trie's branches using a Merkle index.
   170→func (m *SparseMerkleTrie) MerkleProof(index int) ([][]byte, error) {
   171→	if index < 0 {
   172→		return nil, fmt.Errorf("merkle index is negative: %d", index)
   173→	}
   174→	leaves := m.branches[0]
   175→	if index >= len(leaves) {
   176→		return nil, fmt.Errorf("merkle index out of range in trie, max range: %d, received: %d", len(leaves), index)
   177→	}
   178→	merkleIndex := uint(index)
   179→	proof := make([][]byte, m.depth+1)
   180→	for i := uint(0); i < m.depth; i++ {
   181→		subIndex := (merkleIndex / (1 << i)) ^ 1
   182→		if subIndex < uint(len(m.branches[i])) {
   183→			item := bytesutil.ToBytes32(m.branches[i][subIndex])
   184→			proof[i] = item[:]
   185→		} else {
   186→			proof[i] = ZeroHashes[i][:]
   187→		}
   188→	}
   189→	var enc [32]byte
   190→	binary.LittleEndian.PutUint64(enc[:], uint64(len(m.originalItems)))
   191→	proof[len(proof)-1] = enc[:]
   192→	return proof, nil
   193→}
   194→
   195→// ToProto converts the underlying trie into its corresponding
   196→// proto object
   197→func (m *SparseMerkleTrie) ToProto() *protodb.SparseMerkleTrie {
   198→	trie := &protodb.SparseMerkleTrie{
   199→		Depth:         uint64(m.depth),
   200→		Layers:        make([]*protodb.TrieLayer, len(m.branches)),
   201→		OriginalItems: m.originalItems,
   202→	}
   203→	for i, l := range m.branches {
   204→		trie.Layers[i] = &protodb.TrieLayer{
   205→			Layer: l,
   206→		}
   207→	}
   208→	return trie
   209→}
   210→
   211→// VerifyMerkleProofWithDepth verifies a Merkle branch against a root of a trie.
   212→func VerifyMerkleProofWithDepth(root, item []byte, merkleIndex uint64, proof [][]byte, depth uint64) bool {
   213→	if uint64(len(proof)) != depth+1 {
   214→		return false
   215→	}
   216→	node := bytesutil.ToBytes32(item)
   217→	for i := uint64(0); i <= depth; i++ {
   218→		if (merkleIndex & 1) == 1 {
   219→			node = hash.Hash(append(proof[i], node[:]...))
   220→		} else {
   221→			node = hash.Hash(append(node[:], proof[i]...))
   222→		}
   223→		merkleIndex /= 2
   224→	}
   225→	return bytes.Equal(root, node[:])
   226→}
   227→
   228→// VerifyMerkleProof given a trie root, a leaf, the generalized merkle index
   229→// of the leaf in the trie, and the proof itself.
   230→func VerifyMerkleProof(root, item []byte, merkleIndex uint64, proof [][]byte) bool {
   231→	if len(proof) == 0 {
   232→		return false
   233→	}
   234→	return VerifyMerkleProofWithDepth(root, item, merkleIndex, proof, uint64(len(proof)-1))
   235→}
   236→
   237→// Copy performs a deep copy of the trie.
   238→func (m *SparseMerkleTrie) Copy() *SparseMerkleTrie {
