   240→	for i1, srcB1 := range m.branches {
   241→		dstBranches[i1] = bytesutil.SafeCopy2dBytes(srcB1)
   242→	}
   243→
   244→	return &SparseMerkleTrie{
   245→		depth:         m.depth,
   246→		branches:      dstBranches,
   247→		originalItems: bytesutil.SafeCopy2dBytes(m.originalItems),
   248→	}
   249→}
   250→
   251→// NumOfItems returns the num of items stored in
   252→// the sparse merkle trie. We handle a special case
   253→// where if there is only one item stored and it is an
   254→// empty 32-byte root.
   255→func (m *SparseMerkleTrie) NumOfItems() int {
   256→	var zeroBytes [32]byte
   257→	if len(m.originalItems) == 1 && bytes.Equal(m.originalItems[0], zeroBytes[:]) {
   258→		return 0
   259→	}
   260→	return len(m.originalItems)
   261→}
   262→
   263→// ProofFromMerkleLayers creates a proof starting at the leaf index of the merkle layers.
   264→func ProofFromMerkleLayers(layers [][][]byte, startingLeafIndex int) [][]byte {
   265→	// The merkle tree structure looks as follows:
   266→	// [[r1, r2, r3, r4], [parent1, parent2], [root]]
   267→	proof := make([][]byte, 0)
   268→	currentIndex := startingLeafIndex
   269→	for i := 0; i < len(layers)-1; i++ {
   270→		neighborIdx := currentIndex ^ 1
   271→		neighbor := layers[i][neighborIdx]
   272→		proof = append(proof, neighbor)
   273→		currentIndex = currentIndex / 2
   274→	}
   275→	return proof
   276→}
