       "code_excerpt": "// PRIMARY: container/trie/sparse_merkle.go:SparseMerkleTrie.Copy (lines 237-249)
func (m *SparseMerkleTrie) Copy() *SparseMerkleTrie {
	dstBranches := make([][][]byte, len(m.branches))
	for i1, srcB1 := range m.branches {
		dstBranches[i1] = bytesutil.SafeCopy2dBytes(srcB1)
	}
	return &SparseMerkleTrie{
		depth:         m.depth,
		branches:      dstBranches,
		originalItems: bytesutil.SafeCopy2dBytes(m.originalItems),
	}
}
// Uses SafeCopy2dBytes for deep copy. FieldTrie.CopyTrie() copies fieldLayers
// but uses shallow copy of pointers (copy(dstFieldTrie[i], layer)) - potential aliasing."

